package com.nodecockpit.customization;
import java.nio.*;import org.junit.Test;import static org.junit.Assert.*;
public class CardNotificationUniformsTest {
 @Test public void threeFooterShapesDoNotOverwritePillGeometry(){float[][] shapes=new float[13][8];for(int i=0;i<13;i++)shapes[i]=new float[]{i+1,20,30,40,12,0,1,0};ByteBuffer b=ByteBuffer.wrap(CardNotificationUniforms.cluster(new byte[240],shapes,new float[][]{{901,80,18,12}},4,.5f)).order(ByteOrder.nativeOrder());assertEquals(13,b.getFloat(272+12*32),0);assertEquals(1,b.getFloat(272+12*32+24),0);assertEquals(901,b.getFloat(CardNotificationUniforms.BUTTON_OFFSET),0);}

 @Test public void pillBlurZeroDisablesOnlyAdditionalPillDiffusion(){ByteBuffer off=ByteBuffer.wrap(CardNotificationUniforms.cluster(new byte[240],new float[0][],new float[][]{{30,40,20,12}},4,.5f,0)).order(ByteOrder.nativeOrder());assertEquals(0,off.getFloat(252),0);assertEquals(4,off.getFloat(264),0);assertEquals(.5f,off.getFloat(268),0);ByteBuffer full=ByteBuffer.wrap(CardNotificationUniforms.cluster(new byte[240],new float[0][],new float[0][],4,.5f,100)).order(ByteOrder.nativeOrder());assertEquals(1,full.getFloat(252),0);assertEquals(48,full.getFloat(260),.001);}
 @Test public void shaderFastPathsPreserveDistinctSamplingAndAvoidDiscardedFullBlurFetches(){String s=CardNotificationShader.SOURCE;assertTrue(s.contains("dot(cR-cG,cR-cG) + dot(cB-cG,cB-cG) == 0.0"));assertTrue(s.contains("contribution>=1.0)col=mergedBlur(cG,diffusion);else if"));assertTrue(s.contains("contribution<1.0)col=mix"));assertEquals(1,s.split("float control=",-1).length-1);assertTrue(s.indexOf("float control=")<s.indexOf("if(diffusion>0.01 && contribution>=1.0)"));}
 @Test public void expandBlurIsPackedIntoSharedPass(){byte[] packed=CardNotificationUniforms.cluster(new byte[240],new float[][]{{20,30,40,50,24,40,1,0}},new float[][]{{100,80,18,12}},4,.9f);ByteBuffer b=ByteBuffer.wrap(packed).order(ByteOrder.nativeOrder());assertEquals(1,b.getFloat(256),0);assertEquals(14.4f,b.getFloat(260),.001);assertEquals(100,b.getFloat(688),0);assertEquals(12,b.getFloat(700),0);String source=CardNotificationShader.SOURCE;assertTrue(source.contains("float control=u[16].x>0.5?expandMask(p):0.0"));assertFalse(source.contains("mergedBlur(cG)"));assertTrue(source.contains("mergedBlur(cG,diffusion)"));}

 @Test public void sharedShaderStoresGeometryAndPerCardAlphaWithoutChangingOptics(){byte[] base=new byte[240];ByteBuffer.wrap(base).order(ByteOrder.nativeOrder()).putFloat(20,123);float[][] shapes={{20,30,40,50,24,40,.6f,0},{100,120,60,70,24,40,1,0}};ByteBuffer b=ByteBuffer.wrap(CardNotificationUniforms.cluster(base,shapes,6,.8f)).order(ByteOrder.nativeOrder());assertEquals(848,b.capacity());assertEquals(123,b.getFloat(20),0);assertEquals(20,b.getFloat(272),0);assertEquals(.6f,b.getFloat(296),0);assertEquals(100,b.getFloat(304),0);assertEquals(6,b.getFloat(264),0);assertEquals(.8f,b.getFloat(268),0);}
 @Test public void unusedSlotsDisableExtraShapesAndSingleRegionAbiIsPreserved(){byte[] base=new byte[272];base[0]=99;byte[] v=CardNotificationUniforms.normal(base);assertEquals(99,v[0]);for(int i=272;i<v.length;i++)assertEquals(0,v[i]);}
 @Test(expected=IllegalArgumentException.class)public void rejectsTooManyShapes(){CardNotificationUniforms.cluster(new byte[240],new float[14][8],0,0);}
 @Test public void rendererUsesSmoothUnionAndPreservesUncoveredBackdrop(){String s=CardNotificationShader.SOURCE;assertTrue(s.contains("uniform float4 u[53]"));assertTrue(s.contains("mix(d,result.x,h)-k*h*(1.0-h)"));assertTrue(s.contains("float2 n=region.yz;"));assertTrue(s.contains("return content.eval(coord);"));assertFalse(s.contains("return half4(0.0);"));assertFalse(s.contains("lensSDF(p + float2(1.0, 0.0))"));assertTrue(s.contains("max(box.x,box.y)>=result.x+k"));}
}
